(() => {
  const ctx = {
    storageKey: `<%= ctx.storageKey %>`,
    themes: JSON.parse(`<%= ctx.themes %>`),
    ThemeEnum: JSON.parse(`<%= ctx.ThemeEnum %>`)
  };
  function getSystemColorScheme(Theme) {
    if (window.matchMedia("(prefers-color-scheme: dark)").matches) {
      return Theme.dark;
    }
    if (window.matchMedia("(prefers-color-scheme: light)").matches) {
      return Theme.light;
    }
    return null;
  }
  function getThemeValue(preference2, themes, Theme) {
    if (preference2 !== Theme.system) {
      return preference2;
    }
    const systemColorScheme = getSystemColorScheme(Theme);
    if (systemColorScheme && themes.includes(systemColorScheme)) {
      return systemColorScheme;
    }
    const fallbackColorScheme = themes.filter((t) => t !== Theme.system).find((v, i) => i === 0);
    if (fallbackColorScheme) {
      return fallbackColorScheme;
    }
    throw new Error("No default theme provided, Melkor UI needs at least 1 real theme (dark, light or custom)");
  }
  const persistedPreference = window.localStorage.getItem(ctx.storageKey);
  let preference = null;
  if (persistedPreference) {
    preference = persistedPreference;
  }
  if (!ctx.themes.includes(preference)) {
    preference = ctx.themes.find((v, i) => i === 0);
    window.localStorage.removeItem(ctx.storageKey);
  }
  const themeValue = getThemeValue(preference, ctx.themes, ctx.ThemeEnum);
  document.documentElement.setAttribute("data-theme", themeValue);
})();
